ght:800;text-decoration:none;cursor:pointer}.btn:hover{background:#294936}.btn.lime{background:var(--lime);color:var(--bg)}.btn.danger{background:#41231e;color:#ffb09e}.btn.small{padding:7px 9px;font-size:10px}.table{width:100%;border-collapse:collapse}.table th{text-align:left;color:var(--muted);font:500 9px 'DM Mono';letter-spacing:.08em;padding:8px;border-bottom:1px solid var(--line);white-space:nowrap}.table td{padding:12px 8px;border-bottom:1px solid #173022;font-size:11px;vertical-align:top}.table tr:last-child td{border-bottom:0}.status{display:inline-block;padding:4px 6px;border-radius:3px;background:#193a27;color:#bff28d;font:500 9px 'DM Mono';text-transform:uppercase}.status.pending{background:#45391c;color:#ffd875}.status.cancelled,.status.rejected,.status.hidden{background:#40231f;color:#ffad9d}.muted{color:var(--muted)}.thumb{width:48px;height:48px;object-fit:cover;background:#183024;border-radius:5px}.actions{display:flex;gap:7px;flex-wrap:wrap}.form{max-width:1000px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field label{display:block;font-size:10px;font-weight:800;margin:0 0 6px;color:#b8c9bb}.field input,.field textarea,.field select{width:100%;border:1px solid var(--line);border-radius:4px;background:#091810;color:var(--text);padding:10px;outline:0}.field textarea{min-height:100px}.full{grid-column:1/-1}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:16px}.stat{min-height:110px}.stat h2{margin:8px 0 0;font:600 30px Oswald,sans-serif}.stat small{color:var(--muted);font-size:10px}.stat .eyebrow{color:var(--lime);font:500 9px 'DM Mono';letter-spacing:.08em}.dashboard-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:16px;margin-top:16px}.chart{display:grid;grid-template-columns:repeat(12,1fr);align-items:end;gap:5px;height:200px;padding-top:20px}.bar{background:var(--lime);min-height:3px;border-radius:3px 3px 0 0}.chart-label{font:9px 'DM Mono';color:var(--muted);text-align:center;overflow:hidden}.range a{color:var(--muted);text-decoration:none;margin-left:10px;font:500 10px 'DM Mono'}.range a.active{color:var(--lime)}.progress{height:7px;background:#193024;border-radius:10px;overflow:hidden}.progress i{display:block;height:100%;background:var(--lime)}.form-inline{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}.form-inline input,.form-inline select{border:1px solid var(--line);border-radius:4px;background:#091810;color:var(--text);padding:9px}.item-image{width:54px;height:54px;object-fit:cover;border-radius:5px;background:#183024}.timeline{border-left:1px solid var(--line);padding-left:17px}.timeline article{position:relative;margin-bottom:18px}.timeline article:before{content:'';position:absolute;left:-22px;top:4px;width:8px;height:8px;border-radius:50%;background:var(--lime)}@media(max-width:1000px){.stats{grid-template-columns:repeat(2,1fr)}.dashboard-grid{grid-template-columns:1fr}}@media(max-width:700px){.side{width:60px;padding:20px 8px}.brand{font-size:0;margin:6px 10px 38px}.brand i{width:24px;height:24px;margin:0}.nav b,.badge,.logout{display:none}.nav a{justify-content:center}.main{margin-left:60px;padding:24px 15px}.form-grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.hide-sm{display:none}.panel{overflow-x:auto}.table{min-width:720px}}
